#include <iostream>
#include <algorithm>
#include <map>

int main() {
    int a, b;
    std::cin >> a >> b;
    if (a > b) std::swap(a, b);
    std::map<int, int> temp_dict = {
        {1, (b % 6 > 1 && b % 6 < 5) ? 1 : 0},
        {2, {2, 2}, {3, 1}, {7, 1}}.count(b) ? {b, {2, 2}, {3, 1}, {7, 1}}[b] : 0
    };
    int temp_value = 0;
    if (temp_dict.count(a)) temp_value = temp_dict[a];
    int res = (~1) & (a * b - 2 * temp_value);
    std::cout << res << std::endl;
    return 0;
}
